Definition qr_pop (R : qrconc) (b : abatch) (q : qbatchc) (T : list (abatch * qbatchc)) : qrconc :=
  mkQR (qr_loc R) (qr_glob R) (qr_ia R) T [qb_slot q] (combine (b_chunks b) (qb_ks q)) (qr_qpend R).

